import {LESSONS,LESSON_BY_ID,HOME_LESSONS,guideGoal,mainAction,suggestions,lessonTarget} from './guidance-data.js';
import {ITEMS,REGIONS,RECIPES,BUILDINGS} from './data.js';
import {PILLARS} from './rebuild-data.js';
import {POINT_BY_ID,DISTRICTS} from './district-data.js';
import {BPOINT_BY_ID,BMAPS} from './beyond-data.js';
import {firstHarvestStep} from './player-journey.js';
import {regionOpen,regionAccess,gateDestination} from './wayfinding.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,id,label,reason='')=>`<button data-action="${a}" data-id="${esc(id)}" ${reason?'disabled':''}>${esc(label)}</button>`;
const bundle=b=>Object.entries(b||{}).map(([id,n])=>ITEMS[id].name+' ×'+n).join('、')||'无需交付材料';
const checklist=rows=>`<ol class="journal-steps">${rows.map((x,i)=>`<li class="${x.done?'done':!rows.slice(0,i).some(p=>!p.done)?'current':''}"><span>${x.done?'✓':i+1}</span><div>${esc(x.label)}</div></li>`).join('')}</ol>`;
export function featurePrompt(e,id){const l=LESSON_BY_ID[id];if(!l)return '';const done=l.steps(e).every(s=>s.done);return `<div class="feature-purpose"><span>${done?'这项工作带来的变化':'营地需要这项工作'}</span><p>${esc(l.result)}</p>${done?'':button('gFocus',id,'作为当前任务')}</div>`;}
function goalCard(e,goal){if(goal.gate){const d=regionAccess(e,goal.gate);return `<article class="journal-main"><span class="journal-eyebrow">开路任务</span><h2>${goal.title}</h2><p>${d.purpose}</p>${checklist([...d.conditions.map(x=>({label:x.text,done:x.pass})),{label:'在'+REGIONS[d.parent].name+'修复入口',done:d.open}])}<div class="journal-pay">修路需要：${bundle(d.cost)}</div>${button('gGate',goal.gate,'在地图上查看入口')}${button('gMain','','回到家园主线')}</article>`;}
 const l=goal.lesson;if(l)return `<article class="journal-main"><span class="journal-eyebrow">生活委托${l.region?' · '+REGIONS[l.region].name:''}</span><h2>${esc(l.title)}</h2><p class="journal-why">${esc(l.why)}</p>${checklist(l.steps(e))}<div class="journal-outcome"><b>办妥后有什么用</b><p>${esc(l.result)}</p></div><div class="journal-actions">${goal.completed?'<span class="journal-complete">这项工作已办妥</span>':button('gLessonAction',l.id,l.label)}${button('gMain','','继续家园主线')}</div></article>`;
 const q=goal.quest,first=firstHarvestStep(e),action=mainAction(e);if(!q)return `<article class="journal-main"><span class="journal-eyebrow">家园仍在生长</span><h2>选择一个值得期待的明天</h2><p>主线已经完成。接纳新的邻居，恢复地区设施，或让种植与生产更省力。</p>${button('gCatalog','','挑一项生活委托')}</article>`;
 const rows=e.taskRequirements(q.id).map(x=>({label:x.label,done:x.pass}));return `<article class="journal-main"><span class="journal-eyebrow">家园计划 · 第${q.chapter+1}章</span><h2>${q.title}</h2><p class="journal-why">${q.desc}</p>${first?`<div class="journal-next"><small>眼前只做这一步</small><h3>${first.title}</h3><p>${first.text}</p></div>`:checklist(rows)}<div class="journal-outcome"><b>完成后，家园会怎样改变</b><p>${q.outcome}</p></div><div class="journal-pay">${Object.keys(q.cost).length?'交付：'+bundle(q.cost)+'<br>':''}回报：${bundle(q.reward)}${q.money?'，'+q.money+'金币':''}</div><div class="journal-actions">${button('gMainAction','',action.label)}${button('aOpen','', '查看地图')}</div></article>`;}
function recipeCard(e,id){const r=RECIPES.find(r=>r.id===id);if(!r)return '';const jobs=e.c.production.filter(j=>j.recipe===id),why=e.batchReason(id,1),cost=e.effectiveCost(r.cost);return `<section class="journal-recipe"><h3>${id==='trailBread'?'把萝卜做成工作餐':'准备可用的医疗补给'}</h3><p>${esc(r.desc)}</p><div class="journal-flow"><span>${Object.entries(cost).map(([id,n])=>ITEMS[id].name+' '+e.quantityForCost(id,true)+'/'+n).join('、')}</span><i>→</i><span>${bundle(r.out)}</span></div>${Object.entries(cost).filter(([key,n])=>e.quantityForCost(key,true)<n).map(([key])=>`<p class="journal-reason">${ITEMS[key].name}从哪里来：${esc(e.sourceFor(key).text)}</p>`).join('')}<p>需要${r.minutes||0}游戏分钟，关闭菜单后继续加工。</p>${jobs.length?jobs.map(j=>`<div class="journal-job"><span>${j.ready?'成品已做好':Math.ceil(j.remaining)+'分钟后做好'}</span>${j.ready?button('gCollect',j.id,'收好成品'):''}</div>`).join(''):`<p class="journal-reason">${esc(why||'材料与设施齐全，可以开始。')}</p>${button('gCraft',id,'投入材料，开始加工',why)}`}${why&&id==='bandage'?button('gTool','camp:production','先加工布料'):''}${button('gTool','camp:production','查看其他配方与队列')}</section>`;}
export function renderJournal(e,ui={}){const goal=guideGoal(e);if(ui.catalog){const region=ui.filter||'home',list=LESSONS.filter(l=>region==='home'?!l.point:l.region===region).filter(l=>l.unlock(e));return `<div class="journal-page"><div class="journal-top">${button('gBack','','返回当前任务')}<label>想做什么<select id="lesson-region"><option value="home">家园生活</option>${Object.entries({...DISTRICTS,...BMAPS}).filter(([id])=>regionOpen(e,id)).map(([id,d])=>`<option value="${id}" ${region===id?'selected':''}>${d.name}</option>`).join('')}</select></label></div><h2>选一件对家园有用的事</h2><p>已有成果会直接算入进度；这里的任务不会重置设施，也不要求重复交材料。</p><div class="journal-catalog">${list.map(l=>`<article><div><h3>${l.title}</h3><p>${l.result}</p></div>${l.steps(e).every(s=>s.done)?'<span class="journal-complete">已做到</span>':button('gFocus',l.id,'接下这项工作')}</article>`).join('')||'<p>先跟随当前任务开放新的地区。</p>'}</div></div>`;}
 const options=suggestions(e),main=mainAction(e),recipe=!goal.lesson&&!goal.gate&&main.kind==='recipe'?recipeCard(e,main.id):'';return `<div class="journal-page"><header class="journal-top"><span>第${e.s.day}天 · ${REGIONS[e.s.region].name}</span>${button('gCatalog','','选择其他委托')}</header>${goalCard(e,goal)}${recipe}<div class="journal-options">${options.map(l=>`<article><small>也可以先帮一件小事</small><h3>${l.title}</h3><p>${l.result}</p>${button('gFocus',l.id,'看看怎么做')}</article>`).join('')}</div>${e.bactive().length||e.activeEvents().length?`<details class="journal-extra"><summary>收到的消息 · ${e.bactive().length+e.activeEvents().length}件</summary>${e.bactive().map(d=>`<p>${d.name} ${button('gMessage','b:'+d.id,'继续这件事')}</p>`).join('')}${e.activeEvents().map(d=>`<p>${d.name} ${button('gMessage','e:'+d.id,'继续这件事')}</p>`).join('')}</details>`:''}<details class="journal-extra"><summary>营地事务与熟悉的功能</summary><p>可以直接处理已熟悉的工作，不必按任务顺序游玩。</p><div class="journal-tools">${PILLARS.map(p=>button('gManage',p.id,p.name)).join('')}${button('gDistrict','','地区事务')}${button('gBeyond','','边境事务')}</div></details></div>`;}
export function handleGuidanceAction(action,el,ctx){if(!['gJournal','gMain','gFocus','gMainAction','gLessonAction','gCatalog','gBack','gTool','gManage','gCraft','gCollect','gMessage','gGate','gDistrict','gBeyond','aOpen'].includes(action))return false;const {engine:e,ui,showMenu,closeMenu,renderMenu,save,toast}=ctx,id=el.dataset.id||'';const journal=()=>showMenu('journey');const route=target=>{if(!target)return;e.guidance.target=target;e.d.track=null;e.b.track=null;ctx.rebuildUI.target=target;if(e.s.region===target.region){closeMenu();toast('金色路标：'+(target.label||target.name)+'。走近后按 E。');}else showMenu('map',{selected:target.region});};const tool=(menu,tab)=>{ctx.rebuildUI.tool=null;showMenu(menu,{tab,guided:true});};
 if(action==='gJournal'){ui.catalog=false;journal();return true;}if(action==='gMain'){e.guidance.focus=null;e.guidance.target=null;e.d.track=null;e.b.track=null;ctx.rebuildUI.target=null;ui.catalog=false;journal();save();return true;}
 if(action==='gCatalog'){ui.catalog=true;journal();return true;}if(action==='gBack'){ui.catalog=false;journal();return true;}if(action==='gFocus'){if(e.focusLesson(id)){ui.catalog=false;journal();save();}return true;}
 if(action==='gGate'){const t=gateDestination(e,id);route(t);save();return true;}if(action==='aOpen'){showMenu('map',{selected:REGIONS[id]?id:e.s.region});return true;}
 if(action==='gLessonAction'){const l=LESSON_BY_ID[id];if(!l)return true;if(l.point){const target=lessonTarget(e,l);e.guidance.target=target;const near=e.s.region===l.region&&Math.hypot(e.s.player.x-target.x,e.s.player.y-target.y)<=130;if(near)showMenu(l.beyond?'beyond':'districts',{region:l.region,point:l.point,view:'point',simple:true});else route(target);}else{const missing=l.steps(e).findIndex(s=>!s.done);if(l.id==='fishing'){route({region:'farm',x:1040,y:820,label:'林边池塘 · 靠近按 E 抛竿'});}else if(l.id==='cooking'&&missing===1){showMenu('inventory');toast('选择料理，点击食用，效果会显示在生存状态中。');}else if(l.id==='automation'){const id=missing===0?'rain':missing===1?'solar':'drone',b=BUILDINGS[id];if(b.tech&&!e.c.technologies[b.tech])tool('camp','research');else showMenu('build',{focusBuild:id,guided:true});}else if(l.id==='genes'&&missing===0){showMenu('build',{guided:true,focusBuild:'breeder'});}else tool(...l.tool);}save();return true;}
 if(action==='gMainAction'){const a=mainAction(e);if(a.kind==='claim'){e.claimRebuildTask(a.id);e.guidance.target=null;ctx.rebuildUI.target=null;journal();save();}else if(a.kind==='field'){const s=firstHarvestStep(e);if(s?.plot)route({region:'farm',x:s.plot.x,y:s.plot.y,label:s.title});}else if(a.kind==='route')route(a.target);else if(a.kind==='map')showMenu('map',{selected:a.region});else if(a.kind==='recipe'){ui.catalog=false;journal();toast('下方显示这一道配方，材料齐全后即可加工。');}else if(a.kind==='build')showMenu('build',{guided:true,focusBuild:a.id});else if(a.kind==='tool')tool(a.menu,a.tab);else{ui.catalog=true;journal();}return true;}
 if(action==='gTool'){const [menu,tab]=id.split(':');tool(menu,tab);return true;}if(action==='gManage'){ctx.rebuildUI.tool=null;showMenu('rebuild',{tab:id,guided:false});return true;}if(action==='gDistrict'){showMenu('districts',{view:'point',simple:false});return true;}if(action==='gBeyond'){showMenu('beyond',{view:'overview'});return true;}
 if(action==='gCraft'){if(e.c.production.some(j=>j.recipe===id)){toast('这一批已经在加工，完成后再收取。');renderMenu();return true;}e.craft(id);save();renderMenu();return true;}if(action==='gCollect'){if(e.s.region!=='farm'){showMenu('map',{selected:'farm'});toast('成品留在农场，请回家领取。');return true;}e.collectProduction(id);save();renderMenu();return true;}if(action==='gMessage'){const [type,key]=id.split(':');showMenu(type==='b'?'beyond':'rebuild',type==='b'?{view:'events',event:key}:{tab:'events',eventId:key});return true;}
 return true;}
